from pathlib import Path

import pytest

from tools.mirror_sync import mirror_reseed


def test_target_is_canonical_and_fail_closed():
    mirror_reseed._assert_target(
        "mirror/emergent-live"
    )

    with pytest.raises(
        mirror_reseed.MirrorReseedError,
        match="TARGET_NOT_CANONICAL_MIRROR",
    ):
        mirror_reseed._assert_target(
            "Edarsahub_Desarrollo"
        )


def test_force_uses_exact_lease():
    old = "a" * 40

    assert (
        mirror_reseed._force_with_lease_arg(
            old
        )
        == (
            "--force-with-lease="
            "refs/heads/"
            "mirror/emergent-live:"
            + old
        )
    )


def test_force_rejects_invalid_sha():
    with pytest.raises(
        mirror_reseed.MirrorReseedError,
        match="INVALID_OLD_MIRROR_SHA",
    ):
        mirror_reseed._force_with_lease_arg(
            "not-a-sha"
        )


def test_recovery_ref_is_namespaced():
    old = "b" * 40

    ref = mirror_reseed._recovery_ref(
        "20261021T120000Z",
        old,
    )

    assert ref == (
        "refs/heads/backup/"
        "mirror-reseed/"
        "20261021T120000Z-"
        + old[:12]
    )


def test_contract_reuses_canonical_guards():
    source = Path(
        "tools/mirror_sync/mirror_reseed.py"
    ).read_text(
        encoding="utf-8"
    )

    required = [
        "STOP_FLAG.exists()",
        "ENABLE_FLAG.exists()",
        "acquire_writer_lock(",
        "release_writer_lock(",
        "authorized_push(",
        "compare_and_swap(",
        "--force-with-lease=",
        "refs/heads/backup/mirror-reseed/",
        '"production_touched": False',
        '"development_modified":',
    ]

    for token in required:
        assert token in source


def test_recovery_before_replacement():
    source = Path(
        "tools/mirror_sync/mirror_reseed.py"
    ).read_text(
        encoding="utf-8"
    )

    body = source[
        source.index(
            "def reseed_mirror("
        ):
    ]

    assert (
        body.index(
            "_ensure_recovery_ref("
        )
        <
        body.index(
            "_replace_mirror("
        )
    )


def test_no_unprotected_force_push():
    source = Path(
        "tools/mirror_sync/mirror_reseed.py"
    ).read_text(
        encoding="utf-8"
    )

    assert '"--force",' not in source
    assert "'--force'," not in source
    assert "--force-with-lease=" in source


def test_defaults_to_plan_only():
    source = Path(
        "tools/mirror_sync/mirror_reseed.py"
    ).read_text(
        encoding="utf-8"
    )

    assert "execute: bool = False" in source
    assert "if not execute:" in source


def test_development_never_push_target():
    source = Path(
        "tools/mirror_sync/mirror_reseed.py"
    ).read_text(
        encoding="utf-8"
    )

    assert (
        'refs/heads/{DEV_BRANCH}'
        not in source
    )
